function changeList(){return lang==='zh'?[
['全新展开面板','更宽、更充实的三栏布局；顶部反向圆弧与屏幕边缘衔接。放大文字、图标与控件，去掉重复的模块标题。'],
['更完整的 Apple Music 卡片','大封面、歌曲名、歌手、上一首／播放暂停／下一首，以及播放进度。Apple Music 打开时就显示，暂停时也保留。'],
['新的日历视图','月份与七天日期条，突出今天，展示全天和接下来的日程。日历权限不足时提供提示。'],
['独立充电与低电量提示','连接电源显示图标和百分比；低于 20% 时显示橙色提示。音乐开始播放后替换电量提示，结束后自动切回。两种状态等宽。'],
['更稳定的音频状态','播放状态与波形音量分离，静音片段不再仅因没有声音而收起。排除 PowerChime，避免把插电提示音当成音乐。不同播放器的暂停识别仍取决于其输出行为。'],
['重新设计的设置中心','搜索、彩色分类、返回／前进导航，独立的音乐、日历、剪贴板、电池、权限与更新页面。支持中英文及跟随系统语言。'],
['授权状态与操作入口','查看音频可用性、Apple Music 自动化、日历、剪贴板和登录启动状态，并请求授权或前往系统设置。'],
['应用内更新','检查更新、自动检查、自动下载、更新说明和安装重启流程。更新包有独立签名校验。'],
['其他完善','改善 Xcode 预览启动行为；设计与创作、版权署名更新为 PaJii。']
]:[
['An all-new expanded workspace','A wider three-column layout, inverse top corners and larger, clearer controls. Repeated module headings have been removed.'],
['A fuller Apple Music card','Large artwork, song and artist, previous/play/next controls, and playback progress. It stays visible while Music is open, including when paused.'],
['A new view of your day','A month and seven-day date strip highlight today, with all-day and upcoming events and a clear message when access is missing.'],
['Independent power indicators','Plug in to see the power icon and percentage. Below 20%, an amber reminder remains visible. Music replaces the battery indicator while playing; both states use the same width.'],
['More consistent audio state','Playback activity is separate from waveform volume. Silent passages no longer collapse solely because samples are quiet. PowerChime is excluded; pause detection still depends on how each player manages output.'],
['Redesigned settings','Search, colored categories, back/forward navigation, and dedicated music, calendar, clipboard, battery, permissions and update pages. English, Chinese and system language options.'],
['A clear view of permissions','Review audio capture availability, Music automation, calendar, clipboard and login startup. Request access or jump to the relevant system setting.'],
['In-app updates','Manual checks, optional automatic checks and downloads, release notes, installation and relaunch. Update packages are verified with an independent signature.'],
['Finishing touches','Improved Xcode preview startup behavior. Design and copyright credits now identify PaJii.']
]}
function downloadPage(){return `
<section class="hero download-hero"><img class="page-app-icon" src="/assets/orbi-icon.png" width="72" height="72" alt="Orbi"><div class="eyebrow">ORBI 1.2 · AVAILABLE NOW</div><h1>${tr('Your next beginning.<br><span>Starts at the top.</span>','下一次，更顺手。<br><span>从顶部开始。</span>')}</h1><p>${tr('A native workspace for your Mac. Music, calendar, clipboard —<br>and a little more possibility with version 1.2.','为 Mac 而作的原生工作空间。<br>音乐、日历、剪贴板，还有 1.2 带来的更多可能。')}</p><div class="release-card"><div class="release-card-top"><div><span class="release-label">${tr('CURRENT RELEASE','当前版本')}</span><h2>Orbi 1.2</h2><p>${tr('Universal Mac app · By PaJii','Mac 通用版本 · 由 PaJii 创作')}</p></div><a class="pill" href="/downloads/Orbi-1.2.dmg" download="Orbi-1.2.dmg">${tr('Download for Mac','下载 Mac 版')} ↓</a></div><div class="release-facts"><span>macOS ${RELEASE.minimumOS}+</span><span>Apple silicon & Intel</span><span>DMG · ${RELEASE.size||'—'}</span><span>${tr('Version','版本')} 1.2 · Build ${RELEASE.build}</span></div></div><div class="download-note">${tr('Independently distributed. Not Developer ID signed or Apple-notarized. See the first-launch guide below.','独立分发，尚未使用 Developer ID 签名或 Apple 公证。首次打开请阅读下方安装说明。')}</div><a class="textlink" href="#whats-new">${tr('What’s new in 1.2','查看 1.2 更新内容')} ↓</a></section>
<nav class="guide-nav" aria-label="${tr('Download guide sections','下载指南章节')}"><a href="#whats-new">${tr('What’s new','更新内容')}</a><a href="#install">${tr('Install','安装')}</a><a href="#permissions">${tr('Permissions','权限')}</a><a href="#faq">${tr('FAQ','常见问题')}</a></nav>
<section class="section changelog" id="whats-new"><div class="section-heading"><span class="eyebrow">VERSION 1.2 · NOVEMBER 2, 2026</span><h2>${tr('New in the details.<br><span>Better in the everyday.</span>','细节焕新。<br><span>日常，也更新。</span>')}</h2><p>${tr('Here’s everything that changed in Orbi 1.2.','Orbi 1.2 本次更新内容，一次看清楚。')}</p></div><div class="change-list">${changeList().map((c,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><div><h3>${c[0]}</h3><p>${c[1]}</p></div></article>`).join('')}</div></section>
<section class="soft-section" id="install"><div class="section"><div class="section-heading"><span class="eyebrow">01 / INSTALL</span><h2>${tr('Three steps.<br><span>Then make it yours.</span>','三个步骤。<br><span>开启你的 Orbi。</span>')}</h2></div><div class="step-grid">${(lang==='zh'?[
['下载','从上方下载 Orbi-1.2.dmg。安装前请确认你的 Mac 运行 macOS 26.6 或更新版本。'],['拖入应用程序','双击 DMG，把 Orbi 拖到 Applications（应用程序），等待复制完成，再推出磁盘映像。'],['从顶部开始','从“应用程序”中打开 Orbi。鼠标移到屏幕顶部中央展开工作区，菜单栏中可以打开设置。']
]:[['Download','Get Orbi-1.2.dmg above. Make sure your Mac runs macOS 26.6 or later.'],['Drag to Applications','Open the DMG and drag Orbi into Applications. Wait for the copy to finish, then eject the disk image.'],['Start at the top','Open Orbi from Applications. Move your pointer to the top center of the screen to expand the workspace. Open settings from its menu bar icon.']]).map((c,i)=>`<article class="step-card"><span>0${i+1}</span><h3>${c[0]}</h3><p>${c[1]}</p></article>`).join('')}</div><aside class="first-launch"><h3>${tr('About the first launch','关于首次打开')}</h3><p>${tr('Orbi is not currently Developer ID signed or notarized. macOS may block the first launch. If you trust the download, follow Apple’s instructions in System Settings → Privacy & Security. Keep system-wide security protections enabled.','Orbi 当前没有 Developer ID 签名或 Apple 公证，macOS 可能阻止首次打开。如果你信任下载来源，请按 Apple 官方说明在“系统设置 → 隐私与安全性”中处理，并保持系统安全保护开启。')}</p><a class="textlink" href="https://support.apple.com/${lang==='zh'?'zh-cn':'en-us'}/102445" target="_blank" rel="noopener">${tr('Apple’s official guide','查看 Apple 官方说明')} ↗</a></aside></div></section>
<section class="section" id="permissions"><div class="section-heading"><span class="eyebrow">02 / PERMISSIONS</span><h2>${tr('Every permission.<br><span>A clear purpose.</span>','每一项授权。<br><span>都有清楚的用途。</span>')}</h2><p>${tr('Open Settings → Permissions in Orbi to review access. You decide which features to allow.','在 Orbi 的“设置 → 权限”中查看状态，逐项决定是否允许。')}</p></div><div class="permission-grid">${(lang==='zh'?[
['系统音频','用于声音活动和波形。由于系统没有独立授权查询接口，Orbi 会通过实际采集显示“待验证”或“已验证可用”；请播放有声音的内容再验证。'],['Apple Music 自动化','读取歌曲、歌手与封面，并执行播放、暂停和切歌。检查状态需要 Apple Music 处于运行状态。'],['日历','需要完整日历访问权限才能读取今天的日程。仅写入权限无法显示日程。'],['剪贴板','macOS 可设为询问、始终允许或拒绝。自动记录文本需要允许后台读取；历史仅保存在内存中，退出即清除。'],['登录时启动','可在通用设置中启用。如果系统要求批准，请在“登录项与扩展”中允许 Orbi。'],['电池与更新','读取本机电池无需单独授权。检查更新会联网获取版本信息，下载的更新包经过签名验证。']
]:[['System audio','Used for audio activity and the waveform. There is no separate authorization query; Orbi verifies actual capture and shows Not verified or Capture verified. Play audible content to check.'],['Apple Music automation','Reads songs, artists and artwork and controls playback. Music must be running to check authorization.'],['Calendar','Full calendar access is needed to read today’s events. Write-only permission cannot display a schedule.'],['Clipboard','macOS can ask, allow or deny access. Automatic history needs background read access. Text history stays in memory and clears on quit.'],['Launch at login','Enable it in General. If macOS requires approval, allow Orbi in Login Items & Extensions.'],['Battery & updates','Reading local battery information requires no separate grant. Update checks connect online; downloaded packages are signature-verified.']]).map(c=>`<article><h3>${c[0]}</h3><p>${c[1]}</p></article>`).join('')}</div></section>
<section class="soft-section" id="faq"><div class="section faq"><span class="eyebrow">GOOD TO KNOW</span><h2>${tr('A few more things.','你可能还想知道。')}</h2>${faqItems().map(c=>`<details><summary>${c[0]}</summary><p>${c[1]}</p></details>`).join('')}<details><summary>${tr('Verify your download','校验下载文件')}</summary><p>SHA-256 · Orbi-1.2.dmg</p><code class="checksum">${RELEASE.sha256}</code></details></div></section>`}
function faqItems(){return lang==='zh'?[
['从旧版怎么升级？','退出旧版 Orbi，将新版拖入“应用程序”并替换旧应用。没有内置更新器的早期版本，需要先手动安装本次版本一次；之后可在“设置 → 软件更新”中检查更新。'],
['暂停音乐后，音乐卡片还在吗？','Apple Music 运行时，展开面板保留音乐卡片，暂停或没有声音时也会显示。收起状态的音频延伸根据播放活动判断。'],
['为什么充电时显示的是音乐？','音乐播放优先显示音乐状态；停止播放后，若仍连接电源或电量低于 20%，会切回电量提示。两者使用独立且等宽的布局。'],
['所有播放器都可以切歌吗？','歌曲信息、封面和播放控制针对 Apple Music。其他发声应用主要显示应用图标与波形，暂停识别取决于播放器的输出行为。'],
['模块开关会撤销系统权限吗？','不会。模块开关控制展开后的显示。需要撤销权限时，请在 macOS 系统设置中操作。'],
['这是开源应用吗？','Orbi 应用源码不公开。公开 GitHub 仓库用于官网页面、使用说明、更新清单和可下载的安装包。'],
['下载之后没有主窗口，是正常的吗？','正常。Orbi 是菜单栏与刘海应用。移入屏幕顶部中央展开，移开后收起；从菜单栏可以打开设置或退出。']
]:[
['How do I upgrade from an older version?','Quit Orbi, drag the new version into Applications and replace the old app. Early versions without an updater need this manual installation once. Future versions can be checked from Settings → Software Update.'],
['Does the music card stay when paused?','Yes. The expanded Music card stays while Apple Music is running, even when paused or silent. The collapsed audio extension follows playback activity.'],
['Why does music replace the charging indicator?','Music playback takes priority. When it stops, battery information returns if power is connected or the battery is below 20%. They use independent layouts at the same width.'],
['Can every player skip tracks?','Song information, artwork and playback controls are for Apple Music. Other audio apps show their icon and waveform; pause detection depends on their output behavior.'],
['Does hiding a module revoke its permission?','No. Module switches change the expanded workspace. Revoke system access in macOS System Settings.'],
['Is the app open source?','Orbi application source is not public. The public GitHub repository hosts the website, guides, update feed and downloadable installer files.'],
['Is it normal not to see a main window?','Yes. Orbi lives in the menu bar and notch. Move to the top center to expand, move away to collapse, and use its menu bar entry for settings or quitting.']
]}
function aboutPage(){return `<section class="hero about-hero"><img class="page-app-icon" src="/assets/orbi-icon.png" width="78" height="78" alt=""><div class="eyebrow">ORBI · BY PAJII</div><h1>${tr('Little moments.<br><span>A little more effortless.</span>','小小的日常。<br><span>也值得更顺手。</span>')}</h1><p>${tr('One song. One next step. One good idea.<br>A native Mac workspace that keeps them close.','一首歌、下一项日程、刚复制的一句话。<br>我们想让这些小事，都离你近一点。')}</p></section><section class="section split about-story"><div><span class="eyebrow">THE IDEA BEHIND ORBI</span><h2>${tr('Less switching.<br><span>More doing.</span>','少一次切换。<br><span>多一点专注。</span>')}</h2></div><div><p>${tr('Orbi began with the space at the top of the MacBook. What if it could bring together the tools you reach for every day, without another window getting in the way?','Orbi 从 MacBook 顶部的那一点空间出发：能不能把每天会用到的小工具放在一起，不必为了一个小动作，再打开一个窗口？')}</p><p>${tr('Version 1.2 makes that idea clearer: a new expanded shape, a more complete music card, independent battery states and settings that put you in control.','1.2 让这个想法更清晰：新的展开形态、更完整的音乐卡片、独立的电量状态，以及让你自主掌控的设置中心。')}</p></div></section><section class="about-manifesto"><div class="section"><h2>${tr('A little space.<br>A thoughtful place.<br><span>For your everyday.</span>','一点点空间。<br>一点点用心。<br><span>给每天的你。</span>')}</h2></div></section><section class="section about-credits"><span class="eyebrow">DESIGNED & CREATED BY</span><h2>PaJii</h2><p>${tr('Independent creation. A native experience. Made with care for Mac.','独立创作，原生体验。认真打磨每一个日常细节。')}</p><div class="about-meta"><span>Orbi 1.2</span><span>© 2026 PaJii</span><span>Swift · SwiftUI · AppKit</span></div><p class="caption">${tr('Orbi is an independent application and is not affiliated with Apple. Apple, Mac, macOS and Apple Music identify supported platforms and integrations.','Orbi 是独立应用，与 Apple 无隶属关系。Apple、Mac、macOS 和 Apple Music 名称用于说明适用平台与集成功能。')}</p><a class="pill" href="/download/">${tr('Get to know Orbi 1.2','开始使用 Orbi 1.2')} ↗</a></section>`}
